// Métricas de la bitácora. NUNCA guarda el texto de la usuaria.
const seguro = (fn, def = null) => { try { const v = fn(); return v ?? def; } catch (e) { return def; } };

const entrada = $('B02 · Normalizar entrada1').first().json;
const salida  = $('B19 · Unificar salidas1').first().json;
const clasif  = seguro(() => $('B06 · Clasificar (sub-workflow F)1').isExecuted
  ? $('B06 · Clasificar (sub-workflow F)1').all(0)[0]?.json : null);
const usoAgente = seguro(() => $('B14 · Agente de recursos1').isExecuted, false);

// Seudónimo no reversible del ID de Telegram: cuenta usuarias únicas sin guardar su ID.
const seudonimo = (txt) => { let h = 2166136261; for (const ch of String(txt)) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619); } return (h >>> 0).toString(16).padStart(8, '0'); };

const textoAgente = String(salida.output || '');
const derivar = salida.derivar_humano === true || salida.derivar_humano === 'true'
  || textoAgente.includes('persona del equipo');

let categoria, capa, modelo;
if (clasif) {
  categoria = clasif.categoria || 'sin_categoria';
  capa = clasif.capa_deteccion || 'desconocida';
  modelo = clasif.modelo_usado || 'ninguno';
} else if (seguro(() => $('B06 · Clasificar (sub-workflow F)1').isExecuted, false)) {
  categoria = 'emergencia'; capa = 'error_subworkflow'; modelo = 'ninguno';
} else {
  categoria = salida.tipo; capa = 'atajo_sin_ia'; modelo = 'ninguno';
}

return [{ json: {
  fecha_hora: entrada.timestamp,
  usuaria: seudonimo(entrada.usuaria_id),
  tipo_respuesta: salida.tipo || (usoAgente ? 'agente' : 'desconocido'),
  categoria,
  capa_deteccion: capa,
  modelo_clasificador: modelo,
  uso_ia: capa === 'clasificador' || usoAgente,
  derivar_humano: derivar,
  envio_ok: !$input.first().json.error,
  duracion_ms: Date.now() - new Date(entrada.timestamp).getTime(),
} }];

// GUARDIA DE SALIDA (mismo criterio que H4b): ningún teléfono llega a la usuaria si no viene del Documento Madre.
const r = $json;
const respuesta = String(r.output ?? '');
const pasos = Array.isArray(r.intermediateSteps) ? r.intermediateSteps : [];
const obs = pasos.map(p => typeof p.observation === 'string' ? p.observation : JSON.stringify(p.observation ?? '')).join('\n');
const limpiar = s => String(s).replace(/[\s\-().]/g, '');
const obsLimpio = limpiar(obs);

// Líneas fijas por diseño (igual que B11).
const SIEMPRE_PERMITIDOS = ['911', '*765', '5556581111'];

const texto = respuesta.replace(/<[^>]+>/g, '').replace(/ext\.?\s*\d+(\s*,\s*\d+)*/gi, '');
const esTelefono = t => { const d = t.replace('*', ''); return t.startsWith('*') || d.length >= 8 || (d.length === 3 && /^[09]/.test(d)); };
const numeros = (texto.match(/\*?\d[\d\s\-().]*\d/g) || []).map(limpiar).filter(esTelefono);

// Regla 1: números que no devolvió ninguna herramienta.
const noVerificados = numeros.filter(t => !SIEMPRE_PERMITIDOS.includes(t) && !obsLimpio.includes(t));
// Regla 2: si no consultó ninguna herramienta, no puede presentar recursos (emoji de recurso o teléfonos fuera de las líneas fijas).
const presentaRecursos = /[🏛⚖🏠💬]/u.test(respuesta) || numeros.some(t => !SIEMPRE_PERMITIDOS.includes(t));
const sinHerramientas = pasos.length === 0 && presentaRecursos;

// Sin seguimiento humano: el texto seguro no promete que alguien responderá.
const TEXTO_SEGURO = 'No tengo información verificada sobre eso, y prefiero decírtelo a darte un dato que pueda estar equivocado.\nSi quieres hablar con una persona, en la Línea Mujeres te atienden las 24 horas: 55 5658 1111.';

if (noVerificados.length || sinHerramientas) {
  return { json: { ...r, output: TEXTO_SEGURO, derivar_humano: true } };
}
return { json: r };

// MENÚ GUIADO: reconoce los botones. Si no es un botón, el mensaje sigue al clasificador como siempre.
const e = $input.first().json;
const crudo = String(e.mensaje || '').trim();
const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[^a-z0-9ñ· ]/g, ' ').replace(/\s+/g, ' ').trim();
const t = norm(crudo);

const TIPOS = ['Violencia familiar', 'Violencia digital', 'Violación o abuso sexual', 'Acoso u hostigamiento sexual', 'Tentativa de feminicidio'];
const ALCALDIAS = ['Álvaro Obregón', 'Azcapotzalco', 'Benito Juárez', 'Coyoacán', 'Cuajimalpa', 'Cuauhtémoc', 'Gustavo A. Madero', 'Iztacalco', 'Iztapalapa', 'Magdalena Contreras', 'Miguel Hidalgo', 'Milpa Alta', 'Tláhuac', 'Tlalpan', 'Venustiano Carranza', 'Xochimilco', 'Prefiero no decir'];
const tipoDe = s => TIPOS.find(x => norm(x) === norm(s)) || '';
const alcDe = s => ALCALDIAS.find(x => norm(x) === norm(s)) || '';

let op = null;
const MENU = {
  'quiero denunciar': { accion: 'pedir_alcaldia_denuncia' },
  'asesoria presencial gratuita': { accion: 'pedir_alcaldia_asesoria' },
  'numeros de emergencia': { accion: 'emergencia', hoja: 'M1_Emergencias' },
  'refugios': { accion: 'pedir_alcaldia_refugio' },
  'guia paso a paso para mis dudas': { accion: 'que_hago' }, 'que hago': { accion: 'que_hago' },
  'borrar mensajes': { accion: 'salida' }, 'salida rapida': { accion: 'salida' },
  'volver al menu': { accion: 'menu' }, 'menu': { accion: 'menu' }, 'inicio': { accion: 'menu' },
};
if (MENU[t]) op = MENU[t];
else if (tipoDe(crudo)) op = { accion: 'tipo_elegido', tipo: tipoDe(crudo) };
else if (crudo.includes('·')) {
  const [izq, der] = crudo.split('·');
  if (tipoDe(izq) && alcDe(der)) op = { accion: 'denuncia_cerca', tipo: tipoDe(izq), alcaldia: alcDe(der), hoja: 'M4_LugaresDenuncia' };
  const tipo = op ? '' : tipoDe(der);
  if (tipo && norm(izq) === 'donde denunciar') op = { accion: 'donde_denunciar', tipo, hoja: 'M4_LugaresDenuncia' };
  if (tipo && (norm(izq) === 'que llevar' || norm(izq) === 'pasos para denunciar')) op = { accion: 'que_llevar', tipo, hoja: 'M6_TiposDenuncia' };
  if (tipo && norm(izq) === 'documentos') op = { accion: 'denuncia_docs', tipo, hoja: 'M4_LugaresDenuncia' };
  const alc = alcDe(der);
  if (!op && alc && norm(izq) === 'requisitos') op = { accion: 'asesoria_req', alcaldia: alc, hoja: 'M3_AsesoriaAcompanamiento' };
}
else if (crudo.startsWith('⚖') && alcDe(crudo.replace(/^⚖\uFE0F?\s*/, ''))) op = { accion: 'tipos', alcaldia: alcDe(crudo.replace(/^⚖\uFE0F?\s*/, '')) };
else if (crudo.startsWith('🏛') && alcDe(crudo.replace(/^🏛\uFE0F?\s*/, ''))) op = { accion: 'asesoria', alcaldia: alcDe(crudo.replace(/^🏛\uFE0F?\s*/, '')), hoja: 'M3_AsesoriaAcompanamiento' };
else if (crudo.startsWith('🏠') && alcDe(crudo.replace(/^🏠\s*/, ''))) op = { accion: 'refugio', alcaldia: alcDe(crudo.replace(/^🏠\s*/, '')), hoja: 'M2_Refugios' };

return [{ json: { ...e, menu: !!op, salida: op?.accion === 'salida', accion: op?.accion || '', hoja: op?.hoja || '', tipo: op?.tipo || '', alcaldia: op?.alcaldia || '' } }];

// Respuestas del menú guiado SOLO con datos verificados del Documento Madre (sin IA).
const op = $('B05d · Detectar opción del menú1').first().json;
const filas = $input.all().map(i => i.json).filter(r => r && (r.Nombre_Recurso || r.Tipo_Violencia));

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').trim();
const util = s => { const v = String(s ?? '').trim(); return v && !/pendiente|por confirmar/i.test(v) ? v : ''; };
const primeraFrase = s => { const v = util(s); const m = v.match(/^.*?[.!?](\s|$)/); return (m ? m[0] : v).trim(); };
const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

// Dirección con enlace a Google Maps (solo si es una dirección física concreta).
const mapa = dir => {
  const v = util(dir);
  if (!v) return '';
  return v.split(/\s+\/\s+/).map(p => {
    const esFisica = /\d/.test(p) && !/16 alcald|en linea|en línea|remota|confidencial|toda la cdmx/i.test(p);
    const q = p.replace(/^[A-Za-zÁÉÍÓÚáéíóúñ ]+:\s*/, '') + ', Ciudad de México';
    return esFisica ? `📍 <a href="https://www.google.com/maps/search/?api=1&amp;query=${encodeURIComponent(q)}">${esc(p)}</a>` : `📍 ${esc(p)}`;
  }).join('\n');
};
const breve = (r, emoji) => {
  const l = [`${emoji} <b>${esc(r.Nombre_Recurso)}</b>`];
  if (primeraFrase(r.Descripcion)) l.push(esc(primeraFrase(r.Descripcion)));
  if (util(r.Telefono_Contacto)) l.push(`📞 ${esc(r.Telefono_Contacto)}`);
  if (util(r.Horario_Atencion)) l.push(`🕒 ${esc(r.Horario_Atencion)}`);
  if (mapa(r.Direccion_Atencion)) l.push(mapa(r.Direccion_Atencion));
  return l.join('\n');
};
const LUGARES = {
  'Violencia familiar': ['violencia familiar', 'justicia para las mujeres', 'abogadas', 'denuncia digital'],
  'Violencia digital': ['denuncia digital', 'abogadas'],
  'Violación o abuso sexual': ['delitos sexuales', 'justicia para las mujeres'],
  'Acoso u hostigamiento sexual': ['delitos sexuales', 'denuncia digital', 'abogadas'],
  'Tentativa de feminicidio': ['feminicidio', 'justicia para las mujeres'],
};
const lugaresDe = tipo => filas.filter(r => (LUGARES[tipo] || []).some(k => norm(r.Nombre_Recurso + ' ' + r.Descripcion).includes(k))).slice(0, 4);
const cercaDe = alc => filas.filter(r => { const a = norm(r.Alcaldia); return alc === 'Prefiero no decir' || a.includes('todas') || a.includes(norm(alc)); }).slice(0, 4);
const LINEAS_INGRESO = '📞 *765 — Línea SOS Mujeres, 24 horas\n📞 55 5658 1111 — Línea Mujeres (LOCATEL), 24 horas';

let respuesta = '', teclado = 'menu', derivar = false, btn1 = '', btn2 = '';
const sinDatos = txt => { respuesta = txt + ' Si quieres hablar con una persona, en la Línea Mujeres te atienden las 24 horas: 55 5658 1111.'; derivar = true; };

switch (op.accion) {
  case 'menu':
    respuesta = '¿En qué te puedo ayudar? Elige una opción o escríbeme 💜'; break;

  case 'pedir_alcaldia_denuncia':
    respuesta = 'Te acompaño. Para decirte el lugar que te queda más cerca, ¿en qué alcaldía estás?';
    teclado = 'alc_denuncia'; break;

  case 'tipos':
    respuesta = 'Gracias. ¿Qué quieres denunciar?\n\nSi no estás segura, elige lo que más se parezca o cuéntame con tus palabras.';
    teclado = 'tipos'; break;

  case 'denuncia_cerca': {
    const ESPECIAL = {
      'Violencia familiar': ['violencia familiar'], 'Violencia digital': ['denuncia digital'],
      'Violación o abuso sexual': ['delitos sexuales'], 'Acoso u hostigamiento sexual': ['delitos sexuales'],
      'Tentativa de feminicidio': ['feminicidio'],
    };
    const txt = r => norm(r.Nombre_Recurso + ' ' + r.Descripcion);
    const especial = filas.filter(r => (ESPECIAL[op.tipo] || []).some(k => txt(r).includes(k))).slice(0, 2);
    const yaEsp = new Set(especial.map(r => r.Nombre_Recurso));
    const enAlc = op.alcaldia === 'Prefiero no decir' ? [] :
      filas.filter(r => !yaEsp.has(r.Nombre_Recurso) && norm(r.Alcaldia).includes(norm(op.alcaldia)) && !norm(r.Alcaldia).includes('todas')).slice(0, 2);
    const generales = filas.filter(r => !yaEsp.has(r.Nombre_Recurso) && /todas/.test(norm(r.Alcaldia))).slice(0, 1);
    const p = [];
    if (op.tipo === 'Tentativa de feminicidio') { p.push('Si estás en peligro ahora, llama al 911.'); derivar = true; }
    if (enAlc.length) p.push(`📍 <b>Cerca de ti, en ${esc(op.alcaldia)}:</b>\n\n` + enAlc.map(r => breve(r, '⚖️')).join('\n\n'));
    else if (generales.length) p.push((op.alcaldia === 'Prefiero no decir' ? '📍 <b>Cerca de ti:</b>' : `📍 <b>Cerca de ti, en ${esc(op.alcaldia)}:</b>`) + ' puedes acudir a la agencia del Ministerio Público de tu alcaldía.\n\n' + generales.map(r => breve(r, '⚖️')).join('\n\n'));
    if (especial.length) p.push(`🎯 <b>Oficina especializada en ${esc(op.tipo.toLowerCase())}:</b>\n\n` + especial.map(r => breve(r, '⚖️')).join('\n\n'));
    if (!p.filter(x => !x.startsWith('Si estás')).length) { sinDatos(`Todavía estoy verificando los lugares para denunciar <b>${esc(op.tipo.toLowerCase())}</b> y prefiero no darte un dato equivocado.`); break; }
    p.push('💜 Cada fiscalía cuenta con una unidad de apoyo a mujeres: al llegar, puedes pedir que te atiendan ahí.');
    p.push('Toca una dirección para abrirla en el mapa. ¿Quieres saber qué documentos o cosas llevar?');
    respuesta = p.join('\n\n');
    teclado = 'detalle'; btn1 = `📄 Documentos · ${op.tipo}`; btn2 = `👣 Pasos para denunciar · ${op.tipo}`; break;
  }

  case 'tipo_elegido':
    respuesta = (op.tipo === 'Tentativa de feminicidio' ? 'Si estás en peligro ahora, llama al 911.\n\n' : '')
      + `Sobre <b>${esc(op.tipo.toLowerCase())}</b>, ¿qué quieres saber?`;
    if (op.tipo === 'Tentativa de feminicidio') derivar = true;
    teclado = 'detalle'; btn1 = `📍 Dónde denunciar · ${op.tipo}`; btn2 = `👣 Pasos para denunciar · ${op.tipo}`; break;

  case 'donde_denunciar': {
    const l = lugaresDe(op.tipo);
    if (!l.length) { sinDatos(`Todavía estoy verificando los lugares para denunciar <b>${esc(op.tipo.toLowerCase())}</b> y prefiero no darte un dato equivocado.`); break; }
    respuesta = `Puedes denunciar <b>${esc(op.tipo.toLowerCase())}</b> en:\n\n` + l.map(r => breve(r, '⚖️')).join('\n\n')
      + '\n\n💜 Cada fiscalía cuenta con una unidad de apoyo a mujeres: al llegar, puedes pedir que te atiendan ahí.'
      + '\n\nToca una dirección para abrirla en el mapa. ¿Quieres saber qué documentos o cosas llevar?';
    teclado = 'detalle'; btn1 = `📄 Documentos · ${op.tipo}`; btn2 = '🏛️ Asesoría presencial gratuita'; break;
  }

  case 'denuncia_docs': {
    const l = lugaresDe(op.tipo).filter(r => util(r.Requisitos_Ingreso));
    if (!l.length) { sinDatos('Todavía no tengo verificados los documentos que piden.'); break; }
    respuesta = '📄 Esto es lo que piden para denunciar:\n\n' + l.map(r => `⚖️ <b>${esc(r.Nombre_Recurso)}</b>\n${esc(r.Requisitos_Ingreso)}`).join('\n\n')
      + '\n\n¿Quieres conocer los pasos para denunciar?';
    teclado = 'detalle'; btn1 = `👣 Pasos para denunciar · ${op.tipo}`; btn2 = '🏛️ Asesoría presencial gratuita'; break;
  }


  case 'que_llevar': {
    const f = filas.find(r => norm(r.Tipo_Violencia).trim() === norm(op.tipo));
    if (!f) { sinDatos(`Todavía estoy verificando qué necesitas llevar para denunciar <b>${esc(op.tipo.toLowerCase())}</b>.`); break; }
    const p = [];
    if (/sexual|feminicidio/i.test(op.tipo) && util(f.Atencion_urgente)) p.push(`🩺 <b>Primero, tu salud y tu seguridad:</b> ${esc(f.Atencion_urgente)}`);
    if (util(f.Que_llevar)) p.push(`📋 <b>Qué llevar:</b> ${esc(f.Que_llevar)}`);
    if (util(f.Pasos)) p.push(`👣 <b>Pasos:</b> ${esc(f.Pasos)}`);
    if (util(f.Se_puede_sin_denuncia)) p.push(`💜 ${esc(f.Se_puede_sin_denuncia)}`);
    respuesta = p.join('\n\n');
    teclado = 'detalle'; btn1 = `📍 Dónde denunciar · ${op.tipo}`; btn2 = `📄 Documentos · ${op.tipo}`; break;
  }

  case 'pedir_alcaldia_asesoria':
    respuesta = 'Hay lugares donde te asesoran y acompañan gratis, sin necesidad de denunciar.\n\n¿En qué alcaldía estás? Así te digo cuál te queda más cerca.';
    teclado = 'alc_asesoria'; break;

  case 'asesoria': {
    const l = cercaDe(op.alcaldia);
    if (!l.length) { sinDatos('Todavía no tengo verificado un lugar de asesoría cerca de ti.'); break; }
    respuesta = (op.alcaldia === 'Prefiero no decir' ? 'Estos lugares te pueden asesorar:' : `Estos lugares te pueden asesorar si estás en <b>${esc(op.alcaldia)}</b>:`)
      + '\n\n' + l.map(r => breve(r, '🏛️')).join('\n\n') + '\n\nToca una dirección para abrirla en el mapa. ¿Quieres saber qué necesitas llevar?';
    teclado = 'detalle'; btn1 = `📄 Requisitos · ${op.alcaldia}`; btn2 = '⚖️ Quiero denunciar'; break;
  }

  case 'asesoria_req': {
    const l = cercaDe(op.alcaldia).filter(r => util(r.Requisitos_Ingreso));
    if (!l.length) { sinDatos('Todavía no tengo verificados los requisitos.'); break; }
    respuesta = '📄 Esto es lo que necesitas para que te atiendan:\n\n' + l.map(r => `🏛️ <b>${esc(r.Nombre_Recurso)}</b>\n${esc(r.Requisitos_Ingreso)}`).join('\n\n')
      + '\n\n¿Te ayudo con algo más?';
    teclado = 'detalle'; btn1 = '⚖️ Quiero denunciar'; btn2 = '🏠 Refugios'; break;
  }


  case 'emergencia': {
    const lista = filas.filter(r => util(r.Telefono_Contacto)).map(r =>
      `📞 ${esc(r.Telefono_Contacto)} — ${esc(r.Nombre_Recurso)}${util(r.Horario_Atencion) ? ' (' + esc(r.Horario_Atencion) + ')' : ''}`);
    respuesta = lista.length ? 'Toca un número para llamar. Todas las líneas son gratuitas:\n\n' + lista.join('\n\n') : 'Si estás en peligro ahora, llama al 911.';
    break;
  }

  case 'pedir_alcaldia_refugio':
    respuesta = 'Los refugios son lugares seguros y gratuitos para ti y tus hijas e hijos. Por tu seguridad, la mayoría tiene <b>dirección confidencial</b>: no se publica, y para entrar primero una línea de atención valora tu caso y te canaliza.\n\n¿En qué zona estás?';
    teclado = 'alc_refugio'; break;

  case 'refugio': {
    const tipos = filas.slice(0, 3).map(r => `🏠 <b>${esc(r.Nombre_Recurso)}</b>${primeraFrase(r.Descripcion) ? '\n' + esc(primeraFrase(r.Descripcion)) : ''}${util(r.Requisitos_Ingreso) ? '\nRequisitos: ' + esc(r.Requisitos_Ingreso) : ''}`);
    const conTel = filas.filter(r => util(r.Telefono_Contacto)).map(r => `📞 ${esc(r.Telefono_Contacto)} — ${esc(r.Nombre_Recurso)}`);
    respuesta = (op.alcaldia !== 'Prefiero no decir' ? `Gracias. Cuando llames, puedes decir que estás en <b>${esc(op.alcaldia)}</b> para que te canalicen al lugar adecuado.\n\n` : '')
      + 'Llama a cualquiera de estas líneas para pedir tu ingreso a un refugio:\n\n' + [LINEAS_INGRESO, ...conTel].join('\n')
      + (tipos.length ? '\n\nEstos son los tipos de refugio que existen:\n\n' + tipos.join('\n\n') : '');
    break;
  }

  case 'que_hago':
    respuesta = 'Esta es una guía paso a paso para resolver tus dudas 💜\n\nCuéntame con tus palabras qué está pasando o qué te preocupa. Te escucho, te respondo una cosa a la vez y, si quieres, pensamos juntas el siguiente paso: buscar ayuda, denunciar, encontrar un lugar seguro o solo hablar.';
    break;
}

return [{ json: { respuesta, tipo: 'menu_' + op.accion, derivar_humano: derivar, teclado, btn1, btn2, tipo_sel: op.tipo || '', alc_sel: op.alcaldia || '' } }];

// SALIDA RÁPIDA: genera los IDs de los últimos mensajes del chat para borrarlos (Telegram permite borrar
// en chats privados los mensajes de las últimas 48 h, tanto los de la usuaria como los del bot).
const mid = Number($('B01 · Telegram Trigger1').first().json.message.message_id);
const chat = $('B02 · Normalizar entrada1').first().json.chat_id;
const out = [];
for (let id = mid; id > Math.max(0, mid - 150); id--) out.push({ json: { chat_id: chat, message_id: id } });
return out;

// TELÉFONOS TOCABLES: Telegram reconoce los números en formato internacional (+52) y permite llamar al tocarlos.
const r = $json;
let t = String(r.respuesta || r.output || '');
// Quitar negritas que solo envuelven un teléfono.
t = t.replace(/<b>\s*(\*?\d[\d\s\-]*\d(?:\s*ext\.?\s*[\d,\s]+)?)\s*<\/b>/gi, '$1');
// Números de 10 dígitos → +52 (sin duplicar si ya lo tienen).
t = t.replace(/((?:\d[ \-]?){9}\d)(?!\d)/g, (m, num, off, str) => {
  const antes = str.slice(Math.max(0, off - 4), off);
  return /(\+52\s?|\d|\+)$/.test(antes) ? m : '+52 ' + num;
});
return { json: { ...r, respuesta: t } };
